import{_ as a,o as t,c as o,a2 as s}from"./chunks/framework.C3fpVp7C.js";const u=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1792160181000}'),r={name:"faq.md"};function n(i,e,h,d,c,l){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="how-is-this-different-from-oauth-scopes" tabindex="-1">How is this different from OAuth scopes? <a class="header-anchor" href="#how-is-this-different-from-oauth-scopes" aria-label="Permalink to &quot;How is this different from OAuth scopes?&quot;">​</a></h2><p>OAuth scopes are coarse and fixed by the provider. <code>gmail.send</code> lets the holder email anyone. agent-auth scopes constrain parameters, resources and amounts, such as <code>gmail:send to:*@acme.com</code>, and an agent can narrow them further for a sub-agent. agent-auth does not replace the upstream credential. It decides whether a specific request may use it. The <a href="/agent-auth/tool-servers#credential-proxy">credential proxy example</a> keeps the upstream key away from the agent entirely.</p><h2 id="does-the-agent-ever-see-my-real-api-key" tabindex="-1">Does the agent ever see my real API key? <a class="header-anchor" href="#does-the-agent-ever-see-my-real-api-key" aria-label="Permalink to &quot;Does the agent ever see my real API key?&quot;">​</a></h2><p>Not if you use the credential proxy pattern. The agent holds only its agent-auth token. The proxy checks each request and adds the real key to the requests that agent-auth allows.</p><h2 id="can-i-verify-tokens-without-calling-the-server" tabindex="-1">Can I verify tokens without calling the server? <a class="header-anchor" href="#can-i-verify-tokens-without-calling-the-server" aria-label="Permalink to &quot;Can I verify tokens without calling the server?&quot;">​</a></h2><p>Yes. <code>offlineVerifier()</code> checks the signature, expiry and scopes with the public key from <code>/.well-known/jwks.json</code>. It cannot see revocations, use counts or approvals, so it denies scopes that need approval and accepts a revoked token until it expires. Use short TTLs with it.</p><h2 id="what-happens-if-someone-edits-the-database" tabindex="-1">What happens if someone edits the database? <a class="header-anchor" href="#what-happens-if-someone-edits-the-database" aria-label="Permalink to &quot;What happens if someone edits the database?&quot;">​</a></h2><p>SQLite triggers reject <code>UPDATE</code> and <code>DELETE</code> on the audit table, but anyone who can write the file can drop them. <code>agent-auth audit verify</code> then reports the first entry whose hash no longer matches. To also detect a rewrite of the whole log or removed trailing entries, store the <code>head</code> hash somewhere the service cannot write and pass it back with <code>--head</code>.</p><h2 id="does-a-sub-agent-s-use-count-against-the-parent" tabindex="-1">Does a sub-agent&#39;s use count against the parent? <a class="header-anchor" href="#does-a-sub-agent-s-use-count-against-the-parent" aria-label="Permalink to &quot;Does a sub-agent&#39;s use count against the parent?&quot;">​</a></h2><p>Yes. A use of a child token counts against every token above it, so a sub-agent cannot multiply the uses its parent was granted.</p><h2 id="can-i-run-more-than-one-server" tabindex="-1">Can I run more than one server? <a class="header-anchor" href="#can-i-run-more-than-one-server" aria-label="Permalink to &quot;Can I run more than one server?&quot;">​</a></h2><p>Not yet. Storage is one SQLite file, so run a single instance. PostgreSQL storage is on the roadmap.</p><h2 id="is-there-tls" tabindex="-1">Is there TLS? <a class="header-anchor" href="#is-there-tls" aria-label="Permalink to &quot;Is there TLS?&quot;">​</a></h2><p>No. The server binds to loopback by default. Put a TLS-terminating proxy in front of it before you expose it on a network.</p><h2 id="how-do-i-rotate-the-signing-key" tabindex="-1">How do I rotate the signing key? <a class="header-anchor" href="#how-do-i-rotate-the-signing-key" aria-label="Permalink to &quot;How do I rotate the signing key?&quot;">​</a></h2><p>Key rotation is on the roadmap. Today, replacing the key file invalidates every outstanding token.</p><h2 id="which-platforms-does-agent-auth-support" tabindex="-1">Which platforms does agent-auth support? <a class="header-anchor" href="#which-platforms-does-agent-auth-support" aria-label="Permalink to &quot;Which platforms does agent-auth support?&quot;">​</a></h2><p>The npm package runs on Node.js 20 or later.</p>',19)])])}const f=a(r,[["render",n]]);export{u as __pageData,f as default};
